function SkillList() {
  return (
    <div className="space-y-2">
      {SKILLS.map(skill => (
        <div key={skill.label} className="flex items-baseline justify-between gap-3 text-xs">
          <span className="text-text-muted">{skill.label}</span>
          <span className="font-mono text-purple-light shrink-0">{String(skill.years).padStart(2, '0')} yrs</span>
        </div>
      ))}
    </div>
  )
}

